using System;public class Solution{int[]Pick(int[]a,int k){int[]s=new int[k];int top=0,drop=a.Length-k;foreach(int x in a){while(drop>0&&top>0&&s[top-1]<x){top--;drop--;}if(top<k)s[top++]=x;else drop--;}return s;}bool Ge(int[]a,int i,int[]b,int j){while(i<a.Length&&j<b.Length&&a[i]==b[j]){i++;j++;}return j==b.Length||(i<a.Length&&a[i]>b[j]);}int[]Merge(int[]a,int[]b){int[]r=new int[a.Length+b.Length];int i=0,j=0;for(int k=0;k<r.Length;k++)r[k]=Ge(a,i,b,j)?a[i++]:b[j++];return r;}public int[] MaxNumber(int[]a,int[]b,int k){int[]best=new int[k];bool set=false;for(int i=Math.Max(0,k-b.Length);i<=Math.Min(k,a.Length);i++){var r=Merge(Pick(a,i),Pick(b,k-i));if(!set||Ge(r,0,best,0)){best=r;set=true;}}return best;}}
